class Solution {
  public int minChanges(int[] nums, int k) {
    final int M = 1024, INF = 1_000_000_000;
    int[] dp = new int[M];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int start = 0; start < k; start++) {
      int[] freq = new int[M];
      int[] values = new int[(nums.length - start + k - 1) / k]; // distinct values in this group
      int distinct = 0, size = 0;
      for (int i = start; i < nums.length; i += k) {
        if (freq[nums[i]]++ == 0) values[distinct++] = nums[i];
        size++;
      }
      int best = INF;
      for (int x : dp) best = Math.min(best, x);
      int[] next = new int[M];
      java.util.Arrays.fill(next, best + size);
      // only values already in the group can beat changing the whole group, so loop over those alone
      for (int x = 0; x < M; x++) {
        if (dp[x] >= INF) continue;
        for (int j = 0; j < distinct; j++) {
          int v = values[j];
          next[x ^ v] = Math.min(next[x ^ v], dp[x] + size - freq[v]);
        }
      }
      dp = next;
    }
    return dp[0];
  }
}
